import base64, zipfile, io, os

b64_data = ""

zip_bytes = base64.b64decode(b64_data.encode('utf-8'))
os.makedirs('solution', exist_ok=True)
with open('solution.zip', 'wb') as f:
    f.write(zip_bytes)

with zipfile.ZipFile('solution.zip', 'r') as zip_ref:
    zip_ref.extractall('solution')

print('Successfully extracted solution/ package (v7.2 Frontier)!')
